    with open(path, encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if line.startswith("export") and line[6:7] in (" ", "\\t"):
                line = line[6:].lstrip()
            if "=" not in line:
                continue
            key, value = line.split("=", 1)
            values[key.strip()] = _parse_value(value)
